const catBtns = document.getElementsByClassName('catBtn');

Array.from(catBtns).forEach(catBtn => {
  catBtn.addEventListener("click", (e) => {
    context.grafana.locationService.partial({
      'var-pvTreeCategory': e.target.textContent.toLowerCase()
    }, true);
