let series = data.series;
let layout = {
  title: variables.title.current.text,
  yaxis: {
    showline: true,
    title: ""
  },
  yaxis2: {
    title: "",
    overlaying: 'y',
    side: 'right',
  }
};


const config = {
  editable:true
}

if (series[0] != "no data"){


  let traces = [];


  const pvExtraAxis = variables.pvExtraAxis.current.text.split(",");
  series.forEach((s, i) => {

  let name, x, y;

  name = s.name;
  x = Array.from(s.fields[0].values);
  y = Array.from(s.fields[1].values);


  let pvInExtraAxis = pvExtraAxis.some(pv => pv.includes(name));
  let targetAxis = pvInExtraAxis ? 'y2' : 'y1';

  // Fix single-point issue
  let traceMode = 'lines';
  // if(x.length === 1){
  //   traceMode = 'lines+markers';

  //   if(!layout.xaxis) layout.xaxis = {};
  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];
  // }

  traces.push({
    x: x,
    y: y,
    type: 'scatter',
    mode: 'lines',
    line:{
      shape:'hv'
    },
    name: name,
    yaxis: targetAxis,
  });

  if(pvInExtraAxis){
      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;
    } else {
      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;
    }
  });

  return {
      data: traces,
      layout: layout,
      config: config
    };
  }
